import re

x = y = z = e = 0.0
segs = []  # (x0,y0,z0,x1,y1,e)
for line in open('/app/text.gcode'):
    line = line.split(';')[0].strip()
    if not line:
        continue
    cmd = line.split()[0]
    if cmd in ('G0', 'G1'):
        nx, ny, nz, ne = x, y, z, 0.0
        for tok in line.split()[1:]:
            c, v = tok[0], tok[1:]
            if c == 'X': nx = float(v)
            elif c == 'Y': ny = float(v)
            elif c == 'Z': nz = float(v)
            elif c == 'E': ne = float(v)
        if ne > 0 and (nx != x or ny != y):
            segs.append((x, y, nz, nx, ny, ne))
        x, y, z = nx, ny, nz
    elif cmd == 'G91':
        print('G91 relative coords!')

import collections
zs = collections.Counter(round(s[2], 2) for s in segs)
print('total extrusion segs:', len(segs))
print('z levels (top 10):', zs.most_common(10))
xs = [s[3] for s in segs]; ys = [s[4] for s in segs]
print('x range: %.1f .. %.1f' % (min(xs), max(xs)))
print('y range: %.1f .. %.1f' % (min(ys), max(ys)))
EOF
